<?php require __DIR__.'/../includes/auth.php';require __DIR__.'/../config/database.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO plans(name,price,period,features) VALUES(?,?,?,?)");$s->execute([$_POST['name'],$_POST['price'],$_POST['period'],$_POST['features']]);} $rows=$pdo->query("SELECT * FROM plans ORDER BY id DESC")->fetchAll();?><!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 p-8"><main class="mx-auto max-w-5xl"><h1 class="text-3xl font-black">Pricing Plans</h1><form method="post" class="mt-6 grid gap-3 rounded-2xl bg-white p-6 md:grid-cols-4"><input class="border rounded-lg p-3" name="name" placeholder="Plan" required><input class="border rounded-lg p-3" name="price" placeholder="Price" required><input class="border rounded-lg p-3" name="period" placeholder="/month"><input class="border rounded-lg p-3" name="features" placeholder="Features"><button class="rounded-lg bg-blue-600 px-5 py-3 text-white md:col-span-4">Add Plan</button></form><div class="mt-6 rounded-2xl bg-white p-6"><?php foreach($rows as $r):?><p class="border-b py-3"><b><?=$r['name']?></b> — <?=$r['price']?> <?=$r['period']?></p><?php endforeach;?></div></main></body></html>